195	  @override
196	  Future<Either<Failure, Unit>> authenticate() async {
197	    try {
198	      // `biometricOnly: true` (Boundaries/Design Notes) — never lets the
199	      // OS's own device-passcode UI satisfy this call, which would bypass
200	      // Cerne's own PIN screen (Story 2.2) entirely.
201	      // `persistAcrossBackgrounding: true` so a backgrounding mid-prompt
202	      // (e.g. an incoming call) retries on foreground instead of failing
203	      // outright.
204	      final success = await _localAuthentication.authenticate(
205	        localizedReason: 'Autentique-se para acessar o Cerne',
206	        biometricOnly: true,
207	        persistAcrossBackgrounding: true,
208	      );
209	      if (success) {
210	        _emit(VaultStatus.unlocked);
211	        return right(unit);
212	      }
213	      // A `false` result (declined/unavailable, no exception) — status
214	      // stays `locked`; never `Failure.authInvalid` (Boundaries: reserved
215	      // for password login).
216	      return left(
217	        const Failure.malformedResponse(
218	          message: 'Biometric authentication was not successful',
219	        ),
220	      );
221	    } on LocalAuthException catch (error) {
222	      // Covers cancellation, no enrolled biometrics, hardware unavailable,
223	      // etc. (RNF09: never let a platform exception escape unmapped).
224	      return left(Failure.malformedResponse(message: error.toString()));
225	    } catch (error) {
226	      // Any other thrown platform exception (e.g. the plugin's channel
227	      // itself failing) must never escape unmapped either (RNF09) — fail
228	      // closed, same as the documented `LocalAuthException` branch above,
229	      // mirroring `SessionRepositoryImpl.restoreSession()`'s own plain
230	      // `catch`.
231	      return left(Failure.malformedResponse(message: error.toString()));
232	    }
233	  }
