176	  Future<Either<Failure, Unit>> logout() async {
177	    final result = await _remoteDataSource.logout();
178	    // UNCONDITIONAL — must work even offline (Boundaries): regardless of
179	    // whether the backend call above succeeded, the local session is
180	    // cleared and the stream emits unauthenticated so the vault-gate-first
