12	/// (spec-8-1, AD-12: a single data source, single fetch — exactly
13	/// `Resource<T>`'s own shape). A DI `registerLazySingleton` (Boundaries) —
14	/// long-lived like `AccountSettingsCubit`/`MeusRegistrosCubit`, so this
15	/// cubit's constructor subscription to [PendingEntryWriteTracker.
16	/// confirmedWrites] below stays live for the app's whole session, not just
17	/// while Configurações happens to be mounted (Boundaries: "recomputing on
18	/// each event (entry created on another tab while this one stays
19	/// mounted)").
20	///
21	/// Deliberately never caches a previous [load] result across calls
22	/// (Boundaries/Never: "cache the aggregate", AD-15 exclusion; FR-09:
23	/// "computed on demand, never stale") — every [load] re-emits
24	/// [ResourceLoading] first, same as `EntriesSearchCubit._search`.
25	class DashboardCubit extends Cubit<Resource<DashboardAggregate>> {
26	  DashboardCubit(this._repository, this._tracker)
27	    : super(const ResourceIdle()) {
28	    _confirmedSubscription = _tracker.confirmedWrites.listen((_) => load());
29	  }
