36	  /// A monotonic counter guarding against a stale in-flight [load] call's
37	  /// result landing after a newer one has already superseded it (e.g. a
38	  /// `confirmedWrites` event fires while `AccountSettingsScreen.initState`'s
39	  /// own [load] call is still in flight) — same generation-guard
40	  /// convention `EntriesSearchCubit._search`/`MeusRegistrosCubit.
41	  /// _loadFiltered` already use.
42	  int _generation = 0;
43	
44	  /// Boundaries: "`queryParameters: {'period': 'all'}` — fixed; no period
45	  /// selector exists anywhere in the product" — [load]'s one and only
46	  /// call to [DashboardRepository.getAggregate] always passes this.
47	  Future<void> load() async {
48	    final generation = ++_generation;
49	    emit(ResourceLoading());
50	    final result = await _repository.getAggregate(period: 'all');
51	    // Mirrors `EntriesSearchCubit._search`'s own guard: `close()` can race
52	    // this awaited call, and a newer `load()` (constructor-triggered
53	    // `confirmedWrites` event, or a second screen open) can have
54	    // superseded this one while it was in flight.
55	    if (isClosed || generation != _generation) {
56	      return;
57	    }
58	    result.match(
59	      (failure) => emit(ResourceError(failure)),
60	      (aggregate) => emit(ResourceData(aggregate)),
61	    );
62	  }
63	
64	  @override
65	  Future<void> close() async {
66	    await _confirmedSubscription.cancel();
67	    return super.close();
68	  }
